UPDATE SAD200 /* 도로명주소 - 관련지번 */ SET STDG_CD = #{STDG_CD}, CTPV_NM = #{CTPV_NM}, SGG_NM = #{SGG_NM}, STTY_EMD_NM = #{STTY_EMD_NM}, STLI_NM = #{STLI_NM}, MTN_YN = #{MTN_YN}, LOTNO_MNO_NO = #{LOTNO_MNO_NO}, LOTNO_SNO_NO = #{LOTNO_SNO_NO}, MVMN_CS_CD = #{MVMN_CS_CD}, EXISTE_YN = 'Y', LAST_MDFR_ID = 'quartz', LAST_MDFCN_DT = SYSDATE
