	ROAD_NM_CD = #{ROAD_NM_CD} 
	AND UDGD_YN = #{UDGD_YN} 
	AND BMNO_NO = #{BMNO_NO} 
	AND BSNO_NO = #{BSNO_NO} 
	AND LOTNO_SN = #{LOTNO_SN}

