/* jusoProcessSetEmd - Lee JiSeob */
INSERT INTO SAD000 /* 도로명주소 - 읍면동 */
(STDG_CD, CTPV_NM, SGG_NM, STTY_EMD_NM, STLI_NM, EXISTE_YN)
SELECT STDG_CD, CTPV_NM, SGG_NM, STTY_EMD_NM, STLI_NM, NVL(MAX(EXISTE_YN), 'Y') AS EXISTE_YN FROM
( SELECT STDG_CD, CTPV_NM, SGG_NM, STTY_EMD_NM, STLI_NM, NVL(EXISTE_YN, 'Y') AS EXISTE_YN FROM SAD100 /* 도로명주소 - 건물정보 */ WHERE CTPV_NM = #{region}
UNION
SELECT STDG_CD, CTPV_NM, SGG_NM, STTY_EMD_NM, STLI_NM, NVL(EXISTE_YN, 'Y') AS EXISTE_YN FROM SAD200 /* 도로명주소 - 관련지번 */ WHERE CTPV_NM = #{region}
) C
GROUP BY STDG_CD, CTPV_NM, SGG_NM, STTY_EMD_NM, STLI_NM
